import test from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { CAFE_MATERIAL, TrainingEngine } from './training.ts';
import { buildLocalReferenceProposal, LOCAL_REFERENCE_MEDIA_ID, LOCAL_REFERENCE_MEDIA_SHA256 } from './local-reference.ts';
import { TrainingHistorySegmentProjector } from './training-history-segment.ts';
import { exportStudioSession } from './session-export.ts';

// Generated by the identical action sequence below against unmodified frozen v65
// commit 18eaf70df62231e949a608f976c444c68cf84970. These are byte hashes, not rescored facts.
const frozenV65 = {
  cafe: {
    snapshot: '6ada172f4e38ca526f00b1e820bf34df9972f98f89fe50b730c05b6e0b862d85',
    json: '86d899118977d3d572caf8ac1339e1f4afeff5f8080cc7e8da21ced6060dbfba',
    csv: 'de353e65c03c2d7f6b4e8d825887fb027db223db52d832b2191c864890982175',
    partial: '4ab253785c61f3f223fe6ca41f2c59a35c069586cbe3aaab5dccbdf20270ecee',
  },
  corrected: {
    snapshot: 'ded669d784fb2c91d7f9912634989fa9ab7e8c0d1cee70d5491856f5f04c79b6',
    json: '967637386a3676de5aa9f672545e9db41d32d49f89b3404b54ac9eeae8c84cfc',
    csv: '1850df3010d3279a5e9dbef1865c1a1dddc9b0f6e84814be3019fb9fd6132302',
    partial: '53a6af7bd93da20c87db624f3d29847cb24c4f8df3ae1b478c9e44f0fe4ab229',
  },
};
const hash = (value: string) => createHash('sha256').update(value).digest('hex');

test('cafe and corrected-cafe full snapshot, Studio JSON/CSV and partial bytes remain identical to frozen v65', async () => {
  const correction = await buildLocalReferenceProposal({ parent: CAFE_MATERIAL, original: CAFE_MATERIAL, editedCueId: CAFE_MATERIAL.cues[0].id,
    text: 'Could I please have a coffee?', start: 0, end: 6, media: { id: LOCAL_REFERENCE_MEDIA_ID, sha256: LOCAL_REFERENCE_MEDIA_SHA256, durationSeconds: 72 },
    saveRequestId: 'frozen-byte-coffee', version: 'local-ref:frozen-byte-coffee', createdAt: '2026-10-10T00:00:00.000Z' });
  for (const [label, material] of [['cafe', CAFE_MATERIAL], ['corrected', correction.material]] as const) {
    let serial = 0, now = 0;
    const clock = { now: () => now, wallTime: () => new Date(Date.UTC(2026, 9, 10) + now).toISOString(), id: () => `byte-${++serial}` };
    const engine = new TrainingEngine({ material, clock });
    const p = new TrainingHistorySegmentProjector(engine.getSnapshot(), { segmentId: 'byte-segment', writerInstanceId: 'byte-writer', generation: 1, startedAt: clock.wallTime() });
    engine.subscribe(() => p.observe(engine.getSnapshot()));
    engine.input(engine.cue.text, 'typed', { version: 'dom-edit-v1', kind: 'input', inputType: 'insertText', data: engine.cue.text }); now += 123; engine.submit();
    engine.nextCue(); engine.exposeHint('hint'); engine.input('Would you', 'paste'); now += 234; engine.submit();
    const snapshot = engine.getSnapshot(), full = exportStudioSession(snapshot, '2026-10-10T02:00:00.000Z');
    assert.deepEqual({ snapshot: hash(JSON.stringify(snapshot)), json: hash(full.json), csv: hash(full.csv), partial: hash(JSON.stringify(p.getSegment())) }, frozenV65[label]);
  }
});
